mapper.select:
SELECT COUNT(*) FROM equipment_rentals
WHERE user_id = #{userId}
    AND is_approved = TRUE

SELECT COUNT(*)
FROM equipment_rentals
WHERE user_id = #{userId}
AND equipment_id = #{equipmentId}
AND status IN ('RENTED', 'APPROVED')

SELECT er.id, er.user_id AS userId, er.equipment_id AS equipmentId, er.rent_date AS rentDate, er.expected_return_date AS expectedReturnDate, er.return_date AS returnDate, er.extension_count AS extensionCount, er.requested_quantity AS requestedQuantity, er.purpose, er.is_approved AS isApproved, er.approved_by AS approvedBy, er.status, er.created_at AS createdAt, er.updated_at AS updatedAt FROM equipment_rentals er WHERE er.user_id IN
#{userId}
AND er.return_date IS NULL AND er.is_approved = TRUE AND er.status IN ('APPROVED', 'RENTED') ORDER BY er.rent_date DESC
